const TRAPTIP = {"silent k":"The k is silent — it hides at the start: kn-.","silent w":"The w is silent — it hides at the start: wr-.","silent g":"The g is silent — it hides at the start: gn-.","silent p":"The p is silent at the start.","silent b":"The b is silent — you cannot hear it, so you have to remember it.","silent n":"The n at the end is silent: -mn.","silent l":"The l is silent — it hides in the middle.","silent t":"The t is silent — you do not hear it, but it is there.","silent h":"The h is silent — it hides after the first letter.","silent u":"The u is silent — it keeps the g hard.","silent gh":"The gh is silent — you do not hear it, but it is there.","silent s":"The s is silent — you cannot hear it.","silent c":"The c is silent here.","silent d":"The d is silent — you cannot hear it.","ough":"Tricky -ough: the same four letters make many different sounds.","eigh":"eigh says ay, like eight and weigh.","aigh":"aigh says ay, like straight.","augh":"Tricky -augh: you have to remember it.","ie":"i before e, except after c.","ei":"e before i after c — and a few rebels (weird, seize, neighbor).","-ence":"Ends in -ence with an e, not -ance.","-ance":"Ends in -ance with an a, not -ence.","-ent":"Ends in -ent with an e, not -ant.","-ant":"Ends in -ant with an a, not -ent.","-able":"Ends in -able with an a, not -ible.","-ible":"Ends in -ible with an i, not -able.","-tion":"The sh sound is spelled -tion here.","-sion":"The zh or sh sound is spelled -sion here.","-cian":"A person who does something: -cian.","-ious":"Ends in -ious.","-eous":"Ends in -eous.","-ous":"Ends in -ous — never -us.","-ery":"Ends in -ery.","-ary":"Ends in -ary.","-ory":"Ends in -ory.","-ize":"Ends in -ize with a z.","-ise":"Ends in -ise with an s.","ph":"ph says f.","rh":"rh says r — the h is silent.","ps":"ps says s — the p is silent.","sc":"sc says s — the c is along for the ride.","y vowel":"The y is working as a vowel here.","ch":"ch says k here.","tch":"It is -tch, with a sneaky t.","dge":"It is -dge, with a sneaky d."};
